async function getQuote(){if(!token.trim()){setNotice("Enter a Deriv API token to request live proposals. Public analysis remains token-free.");return}if(!ws.current||ws.current.readyState!==1)return;const socket=ws.current;socket.send(JSON.stringify({authorize:token.trim()}));const handler=(ev)=>{let m;try{m=JSON.parse(ev.data)}catch{return}if(m.msg_type==="authorize"){socket.removeEventListener("message",handler);if(m.error){setNotice("Authorization failed: "+m.error.message);return}const req={proposal:1,amount:Number(stake),basis:"stake",contract_type:sig.contract==="DIFFERS"?"DIGITDIFF":"DIGITMATCH",currency:m.authorize.currency||"USD",duration:1,duration_unit:"t",symbol:active,barrier:String(sig.digit??digit)};socket.send(JSON.stringify(req));const qh=(e)=>{let p;try{p=JSON.parse(e.data)}catch{return}if(p.msg_type==="proposal"){socket.removeEventListener("message",qh);setQuote(p.proposal?{...p.proposal,_market:active,_contract:sig.contract,_digit:sig.digit,_at:Date.now()}:null);setNotice(p.error?"Proposal error: "+p.error.message:"Live contract quote received; no order placed.")}};socket.addEventListener("message",qh)}};socket.addEventListener("message",handler)}
async function discoverActiveMarket(){
 if(discoveryBusy)return;
 setDiscoveryBusy(true);setDiscoveryResult(null);
 try{
  const digits=current.map(t=>t.digit);
  const response=await fetch("/api/strategy/discover",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({market:active,digits})});
  const result=await response.json();
  if(!response.ok)throw new Error(result.error||"Strategy discovery failed.");
  setDiscoveryResult({...result,scannedAt:new Date().toISOString()});
  if(Number.isInteger(result.forecast?.targetDigit)&&result.forecast?.strategyId&&current.length){
   const originEpoch=current[current.length-1].epoch;
   const liveLatest=(data.current[active]||[]).slice(-1)[0];
   if(liveLatest&&Number(liveLatest.epoch)===Number(originEpoch)){
    const recordId=active+"|"+result.forecast.strategyId+"|"+originEpoch;
    setShadowRecords(records=>records.some(r=>r.id===recordId)?records:[...records,{id:recordId,market:active,strategyId:result.forecast.strategyId,strategyLabel:result.forecast.strategyLabel,targetDigit:result.forecast.targetDigit,contract:"MATCHES",originEpoch,status:"PENDING",createdAt:new Date().toISOString()}].slice(-500));
   }else{setDiscoveryResult(v=>({...v,message:"Scan result arrived after the market advanced; it was not logged as a future forecast to prevent look-ahead bias."}));}
  }
 }catch(error){setDiscoveryResult({market:active,status:"ERROR",message:error.message||"Strategy discovery unavailable.",tradeEligible:false,decision:"WAIT"});}
 finally{setDiscoveryBusy(false);}
}
async function askAssistant(){
 if(assistantBusy)return;
 setAssistantBusy(true);
 try{
  const freshQuote=quote&&quote._market===active&&quote._contract===sig.contract&&quote._digit===sig.digit&&Date.now()-quote._at<30000;
  const totalPayout=freshQuote&&Number(quote.ask_price)>0?Number(quote.payout)/Number(quote.ask_price):null;
  const selected=stats(current,Math.min(500,current.length));
  const digitChance=sig.digit===undefined?null:selected.a.length?selected.c[sig.digit]/selected.a.length:null;
  const estimatedChance=sig.contract==="MATCHES"?digitChance:sig.contract==="DIFFERS"&&digitChance!==null?1-digitChance:null;
  const response=await fetch("/api/assistant/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({
   market:active,contract:sig.contract,tickCount:current.length,signalQualified:sig.status==="SIGNAL QUALIFIED",
   latencyMs,validationTrials:0,validationWins:0,totalPayout,estimatedChance
  })});
  const data=await response.json();
  if(!response.ok)throw new Error(data.error||"Assistant analysis failed.");
  setAssistantResult(data);
 }catch(error){setAssistantResult({decision:"WAIT",commentary:error.message||"Assistant is temporarily unavailable.",reasons:["Analysis request failed."],aiMode:"UNAVAILABLE"});}
 finally{setAssistantBusy(false);}
}
